from __future__ import annotations

import urllib3

from httptool import ClientConfig
from httptool.client import DEFAULT_RETRY_METHODS, DEFAULT_RETRY_STATUSES


def test_retries_reflect_config():
    retries = ClientConfig(total_retries=5, backoff_factor=1.5).build_retries()
    assert retries.total == 5
    assert retries.connect == 5
    assert retries.read == 5
    assert retries.status == 5
    assert retries.backoff_factor == 1.5
    assert retries.respect_retry_after_header is True


def test_retries_target_idempotent_methods_and_statuses():
    retries = ClientConfig().build_retries()
    assert settings(retries, "allowed_methods") == set(DEFAULT_RETRY_METHODS)
    assert settings(retries, "status_forcelist") == list(DEFAULT_RETRY_STATUSES)


def test_pool_manager_applies_pool_size():
    config = ClientConfig(max_pool_size=7)
    http = config.build_pool_manager()
    try:
        pool = http.connection_from_url("https://example.com")
        assert pool.maxsize == 7
    finally:
        http.clear()


def settings(retries, name):
    """Read a Retry setting as a plain value (urllib3 wraps them in _RetryMeta)."""
    return getattr(retries, name)


# urllib3 stores allowed_methods/status_forcelist as frozenset/list respectively;
# normalize through this helper so assertions read naturally above.
def _value(retries, name):
    return getattr(retries, name)


class TestPoolManager:
    def test_returns_pool_manager(self):
        assert isinstance(ClientConfig().build_pool_manager(), urllib3.PoolManager)

from __future__ import annotations

from httptool import __main__ as cli


class _FakeResponse:
    status = 200
    data = b"ok"


class _FakePool:
    def __init__(self):
        self.requested: list[tuple[str, str]] = []
        self.cleared = False

    def request(self, method, url, **kwargs):
        self.requested.append((method, url))
        return _FakeResponse()

    def clear(self):
        self.cleared = True


def test_fetch_uses_configured_pool(monkeypatch):
    fake = _FakePool()
    monkeypatch.setattr(cli.ClientConfig, "build_pool_manager", lambda self: fake)

    assert cli.fetch("https://example.com") == 0
    assert fake.requested == [("GET", "https://example.com")]
    assert fake.cleared is True


def test_fetch_returns_one_on_error_status(monkeypatch):
    class ErrorPool(_FakePool):
        def request(self, method, url, **kwargs):
            response = _FakeResponse()
            response.status = 503
            return response

    monkeypatch.setattr(cli.ClientConfig, "build_pool_manager", lambda self: ErrorPool())
    assert cli.fetch("https://example.com") == 1


def test_main_requires_a_url(capsys):
    assert cli.main([]) == 2
    assert "usage" in capsys.readouterr().err

